import styled from '@emotion/styled';
import { theme } from 'theme';

const CONTENT_MAX_WIDTH = '512px';
const ILLUSTRATION_SIZE = '200px';

export const StyledKpiDrillDownEmptyCard = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '16px',
  borderRadius: '16px',
  border: `1px solid ${theme.colors.txt.default}14`,
  backgroundColor: theme.colors.specificProperty.noDataBackground,
  padding: '48px 40px',
  width: '100%',
  minHeight: '525px',
  boxSizing: 'border-box',
});

export const StyledKpiDrillDownEmptyContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  gap: '16px',
  textAlign: 'center',
  flex: 1,
});

export const StyledIllustrationWrapper = styled.div({
  '& img': {
    width: ILLUSTRATION_SIZE,
    height: ILLUSTRATION_SIZE,
  },
});

export const StyledTitle = styled.p({
  fontFamily: 'Barlow, sans-serif',
  fontSize: '24px',
  fontWeight: 600,
  lineHeight: '120%',
  color: theme.colors.txt.default,
  margin: 0,
});

export const StyledDescription = styled.p({
  fontFamily: "'Work Sans', sans-serif",
  fontSize: '16px',
  fontWeight: 400,
  lineHeight: '140%',
  color: theme.colors.txt.secondary,
  margin: 0,
  maxWidth: CONTENT_MAX_WIDTH,
});

export const StyledCopyGroup = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '4px',
  maxWidth: CONTENT_MAX_WIDTH,
});

export const StyledActionsWrapper = styled.div({
  display: 'flex',
  gap: '16px',
  width: CONTENT_MAX_WIDTH,
  justifyContent: 'center',

  '& button': {
    width: '242px',
    height: '40px',
    padding: '0',
    borderRadius: '100px',
    border: `1px solid ${theme.colors.txt.default}`,
    background: theme.colors.txt.on.informative.default,
    fontFamily: "'Work Sans', sans-serif",
    fontSize: '16px',
    fontWeight: 500,
    cursor: 'pointer',
    color: theme.colors.txt.default,
    transition: 'background 0.15s ease, color 0.15s ease',
  },

  '& button:hover': {
    background: `${theme.colors.txt.default}0a`,
  },

  '& button[data-variant="primary"]': {
    background: theme.colors.txt.default,
    color: theme.colors.txt.on.informative.default,
  },

  '& button[data-variant="primary"]:hover': {
    background: `${theme.colors.txt.default}cc`,
  },
});
